# Exercise 3 · Test a feature’s label (chapter 2, Read). GPU with Gemma-2-9B, about 3 minutes.
# The same code as on the workshop page. Run from the repo root: python exercises/ex3_test_a_feature_label.py
# Do not edit this file; copy it into work/ to change it.

import numpy as np, torch
from huggingface_hub import hf_hub_download
from transformer_lens import HookedTransformer
torch.set_grad_enabled(False)
model = HookedTransformer.from_pretrained(
    "google/gemma-2-9b", dtype="bfloat16", device="cuda")
p = np.load(hf_hub_download(
    "google/gemma-scope-9b-pt-res",
    "layer_20/width_131k/average_l0_114/params.npz"))
w, b, thr = (torch.tensor(p[k][..., 122774]).float().cuda()
             for k in ("W_enc", "b_enc", "threshold"))

for text in ["living room", "sitting room", "family room", "parlour",
             "lounge", "sofa", "bedroom", "room", "Salon",
             "Le salon est grand", "salon de coiffure"]:
    _, cache = model.run_with_cache(
        text,
        names_filter="blocks.20.hook_resid_post",
        stop_at_layer=21)
    # skip the <bos> token
    pre = cache["blocks.20.hook_resid_post"][0, 1:].float() @ w + b
    print(f"{text:22s} {torch.where(pre > thr, pre, 0.0).max().item():6.1f}")
